class ModelSpec:
    def __init__(self, name, size_gb):
        self.name, self.size_gb = name, size_gb
    @staticmethod
    def parse_size(text):
        return float(text.strip().upper().removesuffix("GB"))
    @classmethod
    def from_line(cls, line):
        name, size = line.split()
        return cls(name, cls.parse_size(size))

