class Room:
    def __init__(self, capacity):
        self.capacity = capacity
    @property
    def capacity(self):
        return self._capacity
    @capacity.setter
    def capacity(self, value):
        if not isinstance(value, int) or value <= 0:
            raise ValueError(f"bad capacity: {value!r}")
        self._capacity = value

check:
r = Room(8)
r.capacity = 12
assert r.capacity == 12, r.capacity
for bad in (0, -3, "8"):
    try:
        r.capacity = bad
    except ValueError:
        pass
    else:
        raise AssertionError(f"capacity = {bad!r} should raise ValueError")
assert r.capacity == 12, "a rejected assignment must keep the old value"
assert isinstance(type(r).__dict__.get("capacity"), property), "capacity should be a @property"
try:
    Room(-1)
except ValueError:
    pass
else:
    raise AssertionError("Room(-1) must raise: write self.capacity = capacity in __init__ so the setter runs")

