            return 0.0
        return super().value() / (2 if self.days_left <= 2 else 1)

from abc import ABC, abstractmethod
class Provider(ABC):
    name = "base"
    @abstractmethod
    def fetch(self, city): ...
    def report(self, city):
        return f"{self.name}: {city} {self.fetch(city):.1f}C"

