from functools import total_ordering
@total_ordering
class Version:
    def __init__(self, text):
        self.key = tuple(int(p) for p in text.split("."))
    def __eq__(self, other):
        return self.key == other.key if isinstance(other, Version) else NotImplemented
    def __lt__(self, other):
        return self.key < other.key if isinstance(other, Version) else NotImplemented
    def __hash__(self):
        return hash(self.key)

class ModelRegistry:
    def __init__(self, models):
        self._models = {m["name"]: m for m in models}
    def __len__(self): return len(self._models)
    def __contains__(self, name): return name in self._models
    def __getitem__(self, name): return self._models[name]
    def __iter__(self): return iter(self._models.values())

